```python
from datetime import time, datetime, date

VOLUME_SIZES = {"db": 40, "media": 900, "photos": 300, "home": 120}


def schedule_backup(volumes, start, end, duration_minutes):
    for name in volumes:
        enqueue(name, start, duration_minutes)


def schedule_weekly():
    volumes = sorted(["photos", "home"], key=lambda v: VOLUME_SIZES[v], reverse=True)
    start, end = time(1, 0), time(5, 0)
    if start >= end:
        raise ValueError("backup window must end after it starts")
    duration = (datetime.combine(date.min, end) - datetime.combine(date.min, start)).seconds // 60
    schedule_backup(volumes, start, end, duration)


def schedule_monthly():
    volumes = sorted(list(VOLUME_SIZES), key=lambda v: VOLUME_SIZES[v], reverse=True)
    start, end = time(0, 30), time(6, 0)
    if start >= end:
        raise ValueError("backup window must end after it starts")
    duration = (datetime.combine(date.min, end) - datetime.combine(date.min, start)).seconds // 60
    schedule_backup(volumes, start, end, duration)
```

